window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64d72b7a1daac4ad"]={"versions": [{"id": "FIG-64d72b7a1daac4ad", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokoll-Ablaufdiagramm (Message Sequence Chart) mit vertikalen Zeitachsen ($t$).</li>\n<li><strong>Funktionale Einordnung:</strong> Dargestellt ist der segmentierte, unquittierte Datentransfer mit bekannter Nachrichtenlänge (<em>Segmented unacknowledged data transfer with known message length</em>) gemäß ISO 10681-2 im AUTOSAR-Basissoftwaremodul <code>FrIsoTp</code> (FlexRay ISO Transport Layer, Spezifikation <code>AUTOSAR_SWS_FlexRayISOTransportLayer</code>, R4.0.3).</li>\n<li><strong>Systemkontext:</strong> Das Modul <code>FrIsoTp</code> vermittelt als Transportschicht im AUTOSAR Classic Communication Stack zwischen dem PDU Router (<code>PduR</code>) oben und dem FlexRay Interface (<code>FrIf</code>) unten. Es übernimmt Segmentierung, Reassemblierung, Flusssteuerung und Pufferverwaltung für Diagnosenachrichten (DCM) oder große Applikations-PDUs über das FlexRay-Kommunikationsnetzwerk.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Lebenslinien):</strong></li>\n<li><strong>Sender / Transmitter (linke Zeitachse):</strong> Sendende <code>FrIsoTp</code>-Instanz (Initiator der Übertragung via <code>FrIsoTp_Transmit()</code>).</li>\n<li><strong>Empfänger / Receiver (rechte Zeitachse):</strong> Empfangende <code>FrIsoTp</code>-Instanz (koordiniert Pufferreservierung über <code>PduR_FrIsoTpStartOfReception()</code>).</li>\n<li><strong>Dargestellte Protokolldateneinheiten (N-PDUs / Frame-Typen nach ISO 10681-2):</strong></li>\n<li><code>StartFrame (STFU)</code>: Start Frame Unacknowledged. Enthält Gesamtnachrichtenlänge (<em>Message Length, ML</em>) und die erste Datennutzlast.</li>\n<li><code>FlowControl_CTS (FC.CTS)</code>: Flow-Control-PDU mit Flow Status <em>Clear To Send</em>. Gibt Pufferverfügbarkeit, Blockgröße (<em>Block Size, BS</em>) und Frame-Separation-Time frei.</li>\n<li><code>ConsecutiveFrame (CF1)</code>: Segmentierte Folge-Frames innerhalb eines Blocks; indiziert durch Sequenzzähler/Toggle-Kennung zur Überwachung der Übertragungsreihenfolge.</li>\n<li><code>ConsecutiveFrame_EOB (CFEOB)</code>: Consecutive Frame End Of Block. Letztes Segment eines definierten Blocks, welches das Ende des autorisierten Sende-Budgets signalisiert und die nächste Flusssteuerungsantwort erzwingt.</li>\n<li><code>LastFrame (LF)</code>: Letztes Segment der Gesamtnachricht (enthält die verbleibende Restnutzlast ohne EOB-Quittungsanforderung).</li>\n<li><strong>Schnittstellen & Interaktion:</strong></li>\n<li><strong>Obere Schicht (<code>PduR</code>):</strong> Aufrufe von <code>PduR_FrIsoTpCopyTxData()</code> (Sender) bzw. <code>PduR_FrIsoTpCopyRxData()</code> (Empfänger).</li>\n<li><strong>Untere Schicht (<code>FrIf</code>):</strong> Physischer Versand/Empfang via <code>FrIf_Transmit()</code>, <code>FrIf_TxConfirmation()</code> und <code>FrIf_RxIndication()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Transfer-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender überträgt einen <code>StartFrame (STFU)</code> an den Empfänger (Auslöser: <code>FrIsoTp_Transmit()</code>, Pufferabruf via <code>PduR_FrIsoTpCopyTxData()</code>).</li>\n<li>Der Empfänger validiert die im STFU übermittelte Nachrichtenlänge via <code>PduR_FrIsoTpStartOfReception()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erste Flusssteuerung (Handshake):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei ausreichendem Puffer signalisiert der Empfänger Empfangsbereitschaft mittels <code>FlowControl_CTS (FC.CTS)</code> (inkl. maximaler Blockgröße $BS$ und minimalem Frame-Abstand).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erster Block-Datentransfer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender feuert asynchron innerhalb des autorisierten Zeitrasters aufeinanderfolgende <code>ConsecutiveFrame (CF1)</code>.</li>\n<li>Der Block wird mit <code>ConsecutiveFrame_EOB (CFEOB)</code> abgeschlossen. Der Sender stoppt die Übertragung und wartet auf eine erneute Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Flusssteuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger prüft den internen Pufferstatus und sendet einen weiteren <code>FlowControl_CTS (FC.CTS)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finaler Block & Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender setzt den Transfer mit <code>ConsecutiveFrame (CF1)</code> fort.</li>\n<li>Die Übertragung endet mit dem <code>LastFrame (LF)</code>.</li>\n<li>Bei erfolgreichem Empfang schließt der Empfänger mit <code>PduR_FrIsoTpRxIndication(..., E_OK)</code> ab; der Sender bestätigt die erfolgreiche Übertragung via <code>PduR_FrIsoTpTxConfirmation(..., E_OK)</code>.</li>\n<li><strong>Abbruchbedingungen & Timeouts:</strong></li>\n<li>Ablauf der Timer $N\\_Ar$, $N\\_As$, $N\\_Cr$ (z. B. Ausbleiben von <code>FC.CTS</code> oder <code>CF</code>) führt zu Verbindungsabbruch (<code>E_NOT_OK</code>) und Det-Fehlermeldung (<code>FRISOTP_E_TIMEOUT_*</code>).</li>\n<li>Senden eines <code>FC.WT</code> (Wait) verzögert den Zyklus; <code>FC.OVFLW</code> (Overflow) bricht den Transfer sofort ab.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Memory-Management:</strong></li>\n<li>Da es sich um einen <em>unacknowledged transfer</em> handelt, erfolgt keine Fehlerkorrektur via Retransmission auf Frame-Ebene (im Gegensatz zum <em>acknowledged transfer</em> mit <code>ACK</code>/<code>NACK</code>). Geht ein CF verloren, bricht die Gesamt-PDU ab.</li>\n<li>Entwickler müssen sicherstellen, dass der PduR-Puffer groß genug konfiguriert ist, um Überläufe (<code>FC.OVFLW</code>) zu verhindern.</li>\n<li><strong>Konfigurationsparameter (AUTOSAR FrIsoTp):</strong></li>\n<li><code>FrIsoTpBlockSize (BS)</code>: Legt fest, nach wie vielen CFs ein <code>CFEOB</code> gesetzt und ein <code>FC.CTS</code> erwartet werden muss.</li>\n<li><code>FrIsoTpBandwidthControl</code>: Steuerung des minimalen Sendeabstands zwischen CFs (Mapping auf FlexRay-Slots / statisches vs. dynamisches Segment).</li>\n<li><code>FrIsoTpTimeoutCr</code>, <code>FrIsoTpTimeoutAs</code>, <code>FrIsoTpTimeoutBs</code>: Exakte Dimensionierung der Protokoll-Timer zur Vermeidung von Deadlocks auf dem Bus.</li>\n<li><strong>FlexRay-Besonderheiten:</strong></li>\n<li>Das Scheduling der N-PDUs muss mit dem FlexRay-Kommunikationszyklus (Cycles, Static/Dynamic Slots) harmonisiert werden; Jitter und Slot-Zuweisung beeinflussen direkt die Einhaltung der ISO-10681-2-Timingvorgaben.</li>\n</ul>"}, {"id": "FIG-93568bc72a86946b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokoll-Ablaufdiagramm (Message Sequence Chart) mit vertikalen Zeitachsen ($t$).</li>\n<li><strong>Funktionale Einordnung:</strong> Dargestellt ist der segmentierte, unquittierte Datentransfer mit bekannter Nachrichtenlänge (<em>Segmented unacknowledged data transfer with known message length</em>) gemäß ISO 10681-2 im AUTOSAR-Basissoftwaremodul <code>FrIsoTp</code> (FlexRay ISO Transport Layer, Spezifikation <code>AUTOSAR_SWS_FlexRayISOTransportLayer</code>, R4.0.3).</li>\n<li><strong>Systemkontext:</strong> Das Modul <code>FrIsoTp</code> vermittelt als Transportschicht im AUTOSAR Classic Communication Stack zwischen dem PDU Router (<code>PduR</code>) oben und dem FlexRay Interface (<code>FrIf</code>) unten. Es übernimmt Segmentierung, Reassemblierung, Flusssteuerung und Pufferverwaltung für Diagnosenachrichten (DCM) oder große Applikations-PDUs über das FlexRay-Kommunikationsnetzwerk.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Lebenslinien):</strong></li>\n<li><strong>Sender / Transmitter (linke Zeitachse):</strong> Sendende <code>FrIsoTp</code>-Instanz (Initiator der Übertragung via <code>FrIsoTp_Transmit()</code>).</li>\n<li><strong>Empfänger / Receiver (rechte Zeitachse):</strong> Empfangende <code>FrIsoTp</code>-Instanz (koordiniert Pufferreservierung über <code>PduR_FrIsoTpStartOfReception()</code>).</li>\n<li><strong>Dargestellte Protokolldateneinheiten (N-PDUs / Frame-Typen nach ISO 10681-2):</strong></li>\n<li><code>StartFrame (STFU)</code>: Start Frame Unacknowledged. Enthält Gesamtnachrichtenlänge (<em>Message Length, ML</em>) und die erste Datennutzlast.</li>\n<li><code>FlowControl_CTS (FC.CTS)</code>: Flow-Control-PDU mit Flow Status <em>Clear To Send</em>. Gibt Pufferverfügbarkeit, Blockgröße (<em>Block Size, BS</em>) und Frame-Separation-Time frei.</li>\n<li><code>ConsecutiveFrame (CF)</code>: Segmentierte Folge-Frames innerhalb eines Blocks; indiziert durch Sequenzzähler/Toggle-Kennung zur Überwachung der Übertragungsreihenfolge.</li>\n<li><code>ConsecutiveFrame_EOB (CFEOB)</code>: Consecutive Frame End Of Block. Letztes Segment eines definierten Blocks, welches das Ende des autorisierten Sende-Budgets signalisiert und die nächste Flusssteuerungsantwort erzwingt.</li>\n<li><code>LastFrame (LF)</code>: Letztes Segment der Gesamtnachricht (enthält die verbleibende Restnutzlast ohne EOB-Quittungsanforderung).</li>\n<li><strong>Schnittstellen & Interaktion:</strong></li>\n<li><strong>Obere Schicht (<code>PduR</code>):</strong> Aufrufe von <code>PduR_FrIsoTpCopyTxData()</code> (Sender) bzw. <code>PduR_FrIsoTpCopyRxData()</code> (Empfänger).</li>\n<li><strong>Untere Schicht (<code>FrIf</code>):</strong> Physischer Versand/Empfang via <code>FrIf_Transmit()</code>, <code>FrIf_TxConfirmation()</code> und <code>FrIf_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Transfer-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender überträgt einen <code>StartFrame (STFU)</code> an den Empfänger (Auslöser: <code>FrIsoTp_Transmit()</code>, Pufferabruf via <code>PduR_FrIsoTpCopyTxData()</code>).</li>\n<li>Der Empfänger validiert die im STFU übermittelte Nachrichtenlänge via <code>PduR_FrIsoTpStartOfReception()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erste Flusssteuerung (Handshake):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei ausreichendem Puffer signalisiert der Empfänger Empfangsbereitschaft mittels <code>FlowControl_CTS (FC.CTS)</code> (inkl. maximaler Blockgröße $BS$ und minimalem Frame-Abstand).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erster Block-Datentransfer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender feuert asynchron innerhalb des autorisierten Zeitrasters aufeinanderfolgende <code>ConsecutiveFrame (CF)</code>.</li>\n<li>Der Block wird mit <code>ConsecutiveFrame_EOB (CFEOB)</code> abgeschlossen. Der Sender stoppt die Übertragung und wartet auf eine erneute Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Flusssteuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger prüft den internen Pufferstatus und sendet einen weiteren <code>FlowControl_CTS (FC.CTS)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finaler Block & Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender setzt den Transfer mit <code>ConsecutiveFrame (CF)</code> fort.</li>\n<li>Die Übertragung endet mit dem <code>LastFrame (LF)</code>.</li>\n<li>Bei erfolgreichem Empfang schließt der Empfänger mit <code>PduR_FrIsoTpRxIndication(..., E_OK)</code> ab; der Sender bestätigt die erfolgreiche Übertragung via <code>PduR_FrIsoTpTxConfirmation(..., E_OK)</code>.</li>\n<li><strong>Abbruchbedingungen & Timeouts:</strong></li>\n<li>Ablauf der Timer $N\\_Ar$, $N\\_As$, $N\\_Cr$ (z. B. Ausbleiben von <code>FC.CTS</code> oder <code>CF</code>) führt zu Verbindungsabbruch (<code>E_NOT_OK</code>) und Det-Fehlermeldung (<code>FRISOTP_E_TIMEOUT_*</code>).</li>\n<li>Senden eines <code>FC.WT</code> (Wait) verzögert den Zyklus; <code>FC.OVFLW</code> (Overflow) bricht den Transfer sofort ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Memory-Management:</strong></li>\n<li>Da es sich um einen <em>unacknowledged transfer</em> handelt, erfolgt keine Fehlerkorrektur via Retransmission auf Frame-Ebene (im Gegensatz zum <em>acknowledged transfer</em> mit <code>ACK</code>/<code>NACK</code>). Geht ein CF verloren, bricht die Gesamt-PDU ab.</li>\n<li>Entwickler müssen sicherstellen, dass der PduR-Puffer groß genug konfiguriert ist, um Überläufe (<code>FC.OVFLW</code>) zu verhindern.</li>\n<li><strong>Konfigurationsparameter (AUTOSAR FrIsoTp):</strong></li>\n<li><code>FrIsoTpBlockSize (BS)</code>: Legt fest, nach wie vielen CFs ein <code>CFEOB</code> gesetzt und ein <code>FC.CTS</code> erwartet werden muss.</li>\n<li><code>FrIsoTpBandwidthControl</code>: Steuerung des minimalen Sendeabstands zwischen CFs (Mapping auf FlexRay-Slots / statisches vs. dynamisches Segment).</li>\n<li><code>FrIsoTpTimeoutCr</code>, <code>FrIsoTpTimeoutAs</code>, <code>FrIsoTpTimeoutBs</code>: Exakte Dimensionierung der Protokoll-Timer zur Vermeidung von Deadlocks auf dem Bus.</li>\n<li><strong>FlexRay-Besonderheiten:</strong></li>\n<li>Das Scheduling der N-PDUs muss mit dem FlexRay-Kommunikationszyklus (Cycles, Static/Dynamic Slots) harmonisiert werden; Jitter und Slot-Zuweisung beeinflussen direkt die Einhaltung der ISO-10681-2-Timingvorgaben.</li>\n</ul>"}, {"id": "FIG-704b9b5a02eab8a3", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokoll-Ablaufdiagramm (Message Sequence Chart) mit vertikalen Zeitachsen ($t$).</li>\n<li><strong>Funktionale Einordnung:</strong> Dargestellt ist der segmentierte, unquittierte Datentransfer mit bekannter Nachrichtenlänge (<em>Segmented unacknowledged data transfer with known message length</em>) gemäß ISO 10681-2 im AUTOSAR-Basissoftwaremodul <code>FrIsoTp</code> (FlexRay ISO Transport Layer, Spezifikation <code>AUTOSAR_SWS_FlexRayISOTransportLayer</code>, R4.0.3).</li>\n<li><strong>Systemkontext:</strong> Das Modul <code>FrIsoTp</code> vermittelt als Transportschicht im AUTOSAR Classic Communication Stack zwischen dem PDU Router (<code>PduR</code>) oben und dem FlexRay Interface (<code>FrIf</code>) unten. Es übernimmt Segmentierung, Reassemblierung, Flusssteuerung und Pufferverwaltung für Diagnosenachrichten (DCM) oder große Applikations-PDUs über das FlexRay-Kommunikationsnetzwerk.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Lebenslinien):</strong></li>\n<li><strong>Sender / Transmitter (linke Zeitachse):</strong> Sendende <code>FrIsoTp</code>-Instanz (Initiator der Übertragung via <code>FrIsoTp_Transmit()</code>).</li>\n<li><strong>Empfänger / Receiver (rechte Zeitachse):</strong> Empfangende <code>FrIsoTp</code>-Instanz (koordiniert Pufferreservierung über <code>PduR_FrIsoTpStartOfReception()</code>).</li>\n<li><strong>Dargestellte Protokolldateneinheiten (N-PDUs / Frame-Typen nach ISO 10681-2):</strong></li>\n<li><code>StartFrame (STFU)</code>: Start Frame Unacknowledged. Enthält Gesamtnachrichtenlänge (<em>Message Length, ML</em>) und die erste Datennutzlast.</li>\n<li><code>FlowControl_CTS (FC.CTS)</code>: Flow-Control-PDU mit Flow Status <em>Clear To Send</em>. Gibt Pufferverfügbarkeit, Blockgröße (<em>Block Size, BS</em>) und Frame-Separation-Time frei.</li>\n<li><code>ConsecutiveFrame (CF)</code>: Segmentierte Folge-Frames innerhalb eines Blocks; indiziert durch Sequenzzähler/Toggle-Kennung zur Überwachung der Übertragungsreihenfolge.</li>\n<li><code>ConsecutiveFrame_EOB (CFEOB)</code>: Consecutive Frame End Of Block. Letztes Segment eines definierten Blocks, welches das Ende des autorisierten Sende-Budgets signalisiert und die nächste Flusssteuerungsantwort erzwingt.</li>\n<li><code>LastFrame (LF)</code>: Letztes Segment der Gesamtnachricht (enthält die verbleibende Restnutzlast ohne EOB-Quittungsanforderung).</li>\n<li><strong>Schnittstellen & Interaktion:</strong></li>\n<li><strong>Obere Schicht (<code>PduR</code>):</strong> Aufrufe von <code>PduR_FrIsoTpCopyTxData()</code> (Sender) bzw. <code>PduR_FrIsoTpCopyRxData()</code> (Empfänger).</li>\n<li><strong>Untere Schicht (<code>FrIf</code>):</strong> Physischer Versand/Empfang via <code>FrIf_Transmit()</code>, <code>FrIf_TxConfirmation()</code> und <code>FrIf_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Transfer-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender überträgt einen <code>StartFrame (STFU)</code> an den Empfänger (Auslöser: <code>FrIsoTp_Transmit()</code>, Pufferabruf via <code>PduR_FrIsoTpCopyTxData()</code>).</li>\n<li>Der Empfänger validiert die im STFU übermittelte Nachrichtenlänge via <code>PduR_FrIsoTpStartOfReception()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erste Flusssteuerung (Handshake):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei ausreichendem Puffer signalisiert der Empfänger Empfangsbereitschaft mittels <code>FlowControl_CTS (FC.CTS)</code> (inkl. maximaler Blockgröße $BS$ und minimalem Frame-Abstand).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erster Block-Datentransfer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender feuert asynchron innerhalb des autorisierten Zeitrasters aufeinanderfolgende <code>ConsecutiveFrame (CF)</code>.</li>\n<li>Der Block wird mit <code>ConsecutiveFrame_EOB (CFEOB)</code> abgeschlossen. Der Sender stoppt die Übertragung und wartet auf eine erneute Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Flusssteuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger prüft den internen Pufferstatus und sendet einen weiteren <code>FlowControl_CTS (FC.CTS)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finaler Block & Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender setzt den Transfer mit <code>ConsecutiveFrame (CF)</code> fort.</li>\n<li>Die Übertragung endet mit dem <code>LastFrame (LF)</code>.</li>\n<li>Bei erfolgreichem Empfang schließt der Empfänger mit <code>PduR_FrIsoTpRxIndication(..., E_OK)</code> ab; der Sender bestätigt die erfolgreiche Übertragung via <code>PduR_FrIsoTpTxConfirmation(..., E_OK)</code>.</li>\n<li><strong>Abbruchbedingungen & Timeouts:</strong></li>\n<li>Ablauf der Timer $N\\_Ar$, $N\\_As$, $N\\_Cr$ (z. B. Ausbleiben von <code>FC.CTS</code> oder <code>CF</code>) führt zu Verbindungsabbruch (<code>E_NOT_OK</code>) und Det-Fehlermeldung (<code>FRISOTP_E_TIMEOUT_*</code>).</li>\n<li>Senden eines <code>FC.WT</code> (Wait) verzögert den Zyklus; <code>FC.OVFLW</code> (Overflow) bricht den Transfer sofort ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Memory-Management:</strong></li>\n<li>Da es sich um einen <em>unacknowledged transfer</em> handelt, erfolgt keine Fehlerkorrektur via Retransmission auf Frame-Ebene (im Gegensatz zum <em>acknowledged transfer</em> mit <code>ACK</code>/<code>NACK</code>). Geht ein CF verloren, bricht die Gesamt-PDU ab.</li>\n<li>Entwickler müssen sicherstellen, dass der PduR-Puffer groß genug konfiguriert ist, um Überläufe (<code>FC.OVFLW</code>) zu verhindern.</li>\n<li><strong>Konfigurationsparameter (AUTOSAR FrIsoTp):</strong></li>\n<li><code>FrIsoTpBlockSize (BS)</code>: Legt fest, nach wie vielen CFs ein <code>CFEOB</code> gesetzt und ein <code>FC.CTS</code> erwartet werden muss.</li>\n<li><code>FrIsoTpBandwidthControl</code>: Steuerung des minimalen Sendeabstands zwischen CFs (Mapping auf FlexRay-Slots / statisches vs. dynamisches Segment).</li>\n<li><code>FrIsoTpTimeoutCr</code>, <code>FrIsoTpTimeoutAs</code>, <code>FrIsoTpTimeoutBs</code>: Exakte Dimensionierung der Protokoll-Timer zur Vermeidung von Deadlocks auf dem Bus.</li>\n<li><strong>FlexRay-Besonderheiten:</strong></li>\n<li>Das Scheduling der N-PDUs muss mit dem FlexRay-Kommunikationszyklus (Cycles, Static/Dynamic Slots) harmonisiert werden; Jitter und Slot-Zuweisung beeinflussen direkt die Einhaltung der ISO-10681-2-Timingvorgaben.</li>\n</ul>"}, {"id": "FIG-e0302e59c78fe3e5", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm / Protokoll-Ablaufdiagramm (Message Sequence Chart) mit vertikalen Zeitachsen ($t$).</li>\n<li><strong>Funktionale Einordnung:</strong> Dargestellt ist der segmentierte, unquittierte Datentransfer mit bekannter Nachrichtenlänge (<em>Segmented unacknowledged data transfer with known message length</em>) gemäß ISO 10681-2 im AUTOSAR-Basissoftwaremodul <code>FrIsoTp</code> (FlexRay ISO Transport Layer, Spezifikation <code>AUTOSAR_SWS_FlexRayISOTransportLayer</code>, R4.0.3).</li>\n<li><strong>Systemkontext:</strong> Das Modul <code>FrIsoTp</code> vermittelt als Transportschicht im AUTOSAR Classic Communication Stack zwischen dem PDU Router (<code>PduR</code>) oben und dem FlexRay Interface (<code>FrIf</code>) unten. Es übernimmt Segmentierung, Reassemblierung, Flusssteuerung und Pufferverwaltung für Diagnosenachrichten (DCM) oder große Applikations-PDUs über das FlexRay-Kommunikationsnetzwerk.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Lebenslinien):</strong></li>\n<li><strong>Sender / Transmitter (linke Zeitachse):</strong> Sendende <code>FrIsoTp</code>-Instanz (Initiator der Übertragung via <code>FrIsoTp_Transmit()</code>).</li>\n<li><strong>Empfänger / Receiver (rechte Zeitachse):</strong> Empfangende <code>FrIsoTp</code>-Instanz (koordiniert Pufferreservierung über <code>PduR_FrIsoTpStartOfReception()</code>).</li>\n<li><strong>Dargestellte Protokolldateneinheiten (N-PDUs / Frame-Typen nach ISO 10681-2):</strong></li>\n<li><code>StartFrame (STFU)</code>: Start Frame Unacknowledged. Enthält Gesamtnachrichtenlänge (<em>Message Length, ML</em>) und die erste Datennutzlast.</li>\n<li><code>FlowControl_CTS (FC.CTS)</code>: Flow-Control-PDU mit Flow Status <em>Clear To Send</em>. Gibt Pufferverfügbarkeit, Blockgröße (<em>Block Size, BS</em>) und Frame-Separation-Time frei.</li>\n<li><code>ConsecutiveFrame (CF)</code>: Segmentierte Folge-Frames innerhalb eines Blocks; indiziert durch Sequenzzähler/Toggle-Kennung zur Überwachung der Übertragungsreihenfolge.</li>\n<li><code>ConsecutiveFrame_EOB (CFEOB)</code>: Consecutive Frame End Of Block. Letztes Segment eines definierten Blocks, welches das Ende des autorisierten Sende-Budgets signalisiert und die nächste Flusssteuerungsantwort erzwingt.</li>\n<li><code>LastFrame (LF)</code>: Letztes Segment der Gesamtnachricht (enthält die verbleibende Restnutzlast ohne EOB-Quittungsanforderung).</li>\n<li><strong>Schnittstellen & Interaktion:</strong></li>\n<li><strong>Obere Schicht (<code>PduR</code>):</strong> Aufrufe von <code>PduR_FrIsoTpCopyTxData()</code> (Sender) bzw. <code>PduR_FrIsoTpCopyRxData()</code> (Empfänger).</li>\n<li><strong>Untere Schicht (<code>FrIf</code>):</strong> Physischer Versand/Empfang via <code>FrIf_Transmit()</code>, <code>FrIf_TxConfirmation()</code> und <code>FrIf_RxIndication()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Transfer-Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender überträgt einen <code>StartFrame (STFU)</code> an den Empfänger (Auslöser: <code>FrIsoTp_Transmit()</code>, Pufferabruf via <code>PduR_FrIsoTpCopyTxData()</code>).</li>\n<li>Der Empfänger validiert die im STFU übermittelte Nachrichtenlänge via <code>PduR_FrIsoTpStartOfReception()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erste Flusssteuerung (Handshake):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei ausreichendem Puffer signalisiert der Empfänger Empfangsbereitschaft mittels <code>FlowControl_CTS (FC.CTS)</code> (inkl. maximaler Blockgröße $BS$ und minimalem Frame-Abstand).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Erster Block-Datentransfer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender feuert asynchron innerhalb des autorisierten Zeitrasters aufeinanderfolgende <code>ConsecutiveFrame (CF)</code>.</li>\n<li>Der Block wird mit <code>ConsecutiveFrame_EOB (CFEOB)</code> abgeschlossen. Der Sender stoppt die Übertragung und wartet auf eine erneute Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweite Flusssteuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Empfänger prüft den internen Pufferstatus und sendet einen weiteren <code>FlowControl_CTS (FC.CTS)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finaler Block & Abschluss:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Sender setzt den Transfer mit <code>ConsecutiveFrame (CF)</code> fort.</li>\n<li>Die Übertragung endet mit dem <code>LastFrame (LF)</code>.</li>\n<li>Bei erfolgreichem Empfang schließt der Empfänger mit <code>PduR_FrIsoTpRxIndication(..., E_OK)</code> ab; der Sender bestätigt die erfolgreiche Übertragung via <code>PduR_FrIsoTpTxConfirmation(..., E_OK)</code>.</li>\n<li><strong>Abbruchbedingungen & Timeouts:</strong></li>\n<li>Ablauf der Timer $N\\_Ar$, $N\\_As$, $N\\_Cr$ (z. B. Ausbleiben von <code>FC.CTS</code> oder <code>CF</code>) führt zu Verbindungsabbruch (<code>E_NOT_OK</code>) und Det-Fehlermeldung (<code>FRISOTP_E_TIMEOUT_*</code>).</li>\n<li>Senden eines <code>FC.WT</code> (Wait) verzögert den Zyklus; <code>FC.OVFLW</code> (Overflow) bricht den Transfer sofort ab.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Memory-Management:</strong></li>\n<li>Da es sich um einen <em>unacknowledged transfer</em> handelt, erfolgt keine Fehlerkorrektur via Retransmission auf Frame-Ebene (im Gegensatz zum <em>acknowledged transfer</em> mit <code>ACK</code>/<code>NACK</code>). Geht ein CF verloren, bricht die Gesamt-PDU ab.</li>\n<li>Entwickler müssen sicherstellen, dass der PduR-Puffer groß genug konfiguriert ist, um Überläufe (<code>FC.OVFLW</code>) zu verhindern.</li>\n<li><strong>Konfigurationsparameter (AUTOSAR FrIsoTp):</strong></li>\n<li><code>FrIsoTpBlockSize (BS)</code>: Legt fest, nach wie vielen CFs ein <code>CFEOB</code> gesetzt und ein <code>FC.CTS</code> erwartet werden muss.</li>\n<li><code>FrIsoTpBandwidthControl</code>: Steuerung des minimalen Sendeabstands zwischen CFs (Mapping auf FlexRay-Slots / statisches vs. dynamisches Segment).</li>\n<li><code>FrIsoTpTimeoutCr</code>, <code>FrIsoTpTimeoutAs</code>, <code>FrIsoTpTimeoutBs</code>: Exakte Dimensionierung der Protokoll-Timer zur Vermeidung von Deadlocks auf dem Bus.</li>\n<li><strong>FlexRay-Besonderheiten:</strong></li>\n<li>Das Scheduling der N-PDUs muss mit dem FlexRay-Kommunikationszyklus (Cycles, Static/Dynamic Slots) harmonisiert werden; Jitter und Slot-Zuweisung beeinflussen direkt die Einhaltung der ISO-10681-2-Timingvorgaben.</li>\n</ul>"}], "trans": [{"from": "FIG-64d72b7a1daac4ad", "to": "FIG-93568bc72a86946b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>ConsecutiveFrame</code>: Die Frame-Kurzbezeichnung wurde in allen drei Vorkommen von <code>(CF1)</code> auf <code>(CF)</code> korrigiert.</li>\n<li><code>Lebenslinien</code>: Am oberen Diagrammrand wurde eine gestrichelte Begrenzungslinie zwischen den beiden vertikalen Zeitachsen ergänzt.</li>\n</ul>"}, {"from": "FIG-93568bc72a86946b", "to": "FIG-704b9b5a02eab8a3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-704b9b5a02eab8a3", "to": "FIG-e0302e59c78fe3e5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
